+    let a_lines: Vec<usize> = (0..lines.len()).filter(|&i| lines[i].contains('A')
+        && lines[i].split(' ').any(|t| t.starts_with('A') && word(t).is_some())).collect();
+    let want = ["G0 A0", "G0 A90", "G0 A180", "G0 A-90"];
